{"file_path":"tests/test_spec.py","content":"import pytest

from safety_evals.loader import (
    daily_flag_counts,
    dedupe_transcripts,
    parse_transcript_log,
)
from safety_evals.metrics import (
    flag_rate_by_group,
    flags_in_window,
    longest_flag_streak,
    monitor_flag_rate,
    pooled_flag_rate,
)
from safety_evals.report import monitor_summary, top_flagged_groups


def event(id_, day, flagged):
    return {"id": id_, "day": day, "flagged": flagged}


def test_monitor_flag_rate_counts_none_in_denominator():
    assert monitor_flag_rate([event("a", 1, True), event("b", 1, None)]) == 0.5
    assert monitor_flag_rate([event("a", 1, None)]) == 0.0
    assert monitor_flag_rate([]) == 0.0


def test_pooled_rate_weights_transcripts_and_handles_empty_groups():
    groups = {"a": [event("a", 1, True)], "b": [event("b", 1, False)] * 3, "c": []}
    assert pooled_flag_rate(groups) == 0.25
    assert pooled_flag_rate({}) == 0.0
    assert pooled_flag_rate({"empty": []}) == 0.0


@pytest.mark.parametrize("days, expected", [(0, 0), (1, 3), (2, 5), (3, 6), (10, 6)])
def test_flags_in_window(days, expected):
    assert flags_in_window([1, 2, 3], days) == expected
    assert flags_in_window([], days) == 0


def test_parse_log_fields_and_skipped_lines():
    lines = ["\n", "  # a comment, with commas\n", " \t ", " a , 2 , 1 ",
             "b, -1, 0", "c,3,   "]
    assert parse_transcript_log(lines) == [
        event("a", 2, True), event("b", -1, False), event("c", 3, None)
    ]


@pytest.mark.parametrize("bad_line", ["a,1", "a,1,1,extra", "a,no,1", "a,1,true"])
def test_parse_log_errors_include_original_line_number(bad_line):
    with pytest.raises(ValueError, match=r"line 4\b"):
        parse_transcript_log(["", " # comment", "ok,1,0", bad_line])


def test_dedupe_last_duplicate_id_wins_and_results_are_sorted():
    events = [event("z", 1, True), event("b", 2, True), event("a", 2, False),
              event("z", 2, None), event("b", 0, False)]
    assert dedupe_transcripts(events) == [events[4], events[2], events[3]]
    assert dedupe_transcripts([]) == []


def test_daily_counts_include_empty_days_and_exclude_outside_range():
    events = [event("a", 0, True), event("b", 1, True), event("c", 1, True),
              event("d", 2, None), event("e", 3, False), event("f", 4, True)]
    assert daily_flag_counts(events, 1, 3) == [2, 0, 0]
    assert daily_flag_counts([], 1, 3) == [0, 0, 0]
    assert daily_flag_counts(events, 3, 1) == []


def test_summary_pooled_rate_recent_calendar_days_and_nonempty_groups():
    groups = {"empty": [], "a": [event("a", 1, True)],
              "b": [event("b", 4, True), event("c", 4, False), event("d", 4, None)]}
    assert monitor_summary(groups, 2) == {"rate": 0.5, "recent": 1, "groups": 2}
    assert monitor_summary(groups, 0)["recent"] == 0
    assert monitor_summary(groups, 20)["recent"] == 2
    assert monitor_summary({"empty": []}, 1) == {"rate": 0.0, "recent": 0, "groups": 0}
    assert monitor_summary({}, 1) == {"rate": 0.0, "recent": 0, "groups": 0}
    assert monitor_summary({"g": [event("a", 1, True)] + [event("b", 1, False)] * 2}, 1)["rate"] == 0.333


def test_top_flagged_groups_excludes_empty_and_breaks_ties_by_name():
    groups = {"z": [event("z", 1, True)], "empty": [], "a": [event("a", 1, True)],
              "b": [event("b", 1, False)]}
    assert top_flagged_groups(groups, 10) == ["a", "z", "b"]
    assert top_flagged_groups(groups, 1) == ["a"]
    assert top_flagged_groups(groups, 0) == []


def test_flag_rate_by_group_sorted_with_empty_as_none():
    groups = {"z": [], "b": [event("b", 1, False)], "a": [event("a", 1, True)]}
    result = flag_rate_by_group(groups)
    assert result == {"a": 1.0, "b": 0.0, "z": None}
    assert list(result) == ["a", "b", "z"]


def test_longest_streak_requires_positive_consecutive_counts():
    assert longest_flag_streak([1, 2, 0, 3, -1, 2, 3, 4]) == 3
    assert longest_flag_streak([0, -1, 0]) == 0
    assert longest_flag_streak([]) == 0
